import{_ as e,c as i,o as t,aj as n}from"./chunks/framework.CDhdelVI.js";const g=JSON.parse('{"title":"Sicilian Pan Pizza","description":"A thick, airy Sicilian pan pizza with bread-forward chew, open crumb, and a crisp oiled bottom.","frontmatter":{"title":"Sicilian Pan Pizza","description":"A thick, airy Sicilian pan pizza with bread-forward chew, open crumb, and a crisp oiled bottom.","head":[["meta",{"name":"description","content":"A thick, airy Sicilian pan pizza with bread-forward chew, open crumb, and a crisp oiled bottom."}],["meta",{"property":"og:title","content":"Sicilian Pan Pizza"}],["meta",{"property":"og:description","content":"A thick, airy Sicilian pan pizza with bread-forward chew, open crumb, and a crisp oiled bottom."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:url","content":"https://kitchenratio.com/recipes/sicilian-pan-pizza.html"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Sicilian Pan Pizza"}],["meta",{"name":"twitter:description","content":"A thick, airy Sicilian pan pizza with bread-forward chew, open crumb, and a crisp oiled bottom."}],["link",{"rel":"canonical","href":"https://kitchenratio.com/recipes/sicilian-pan-pizza.html"}]]},"headers":[],"relativePath":"recipes/sicilian-pan-pizza.md","filePath":"recipes/sicilian-pan-pizza.md"}'),r={name:"recipes/sicilian-pan-pizza.md"};function l(o,a,s,d,c,h){return t(),i("div",null,[...a[0]||(a[0]=[n('<h1 id="sicilian-pan-pizza" tabindex="-1">Sicilian Pan Pizza <a class="header-anchor" href="#sicilian-pan-pizza" aria-label="Permalink to “Sicilian Pan Pizza”">​</a></h1><p>This is the bread-forward pan pie: thicker than New York, lighter than it looks, and built around a long pan proof. If Detroit is edge-caramel drama, Sicilian is crumb and structure. Use the <a href="https://kitchenratio.com/calculator/pizza/sicilian" target="_blank" rel="noreferrer">KitchenRatio Calculator</a> to scale any batch size.</p><div class="recipe-glance"><div class="recipe-glance-card"><strong>Style</strong><span>Thicker pan pizza with bread-forward chew, open crumb, and crisp oiled base.</span></div><div class="recipe-glance-card"><strong>Yield</strong><span>Example batch fits a 9x13-inch pan for a classic medium-thick profile.</span></div><div class="recipe-glance-card"><strong>Best For</strong><span>Long pan proofs, rectangular pans, and softer, thicker tray slices.</span></div></div><div class="info custom-block"><p class="custom-block-title">Testing Status</p><p>This formula is still being tested and refined.</p></div><h2 id="baker-s-testing-range" tabindex="-1">Baker&#39;s % (Testing Range) <a class="header-anchor" href="#baker-s-testing-range" aria-label="Permalink to “Baker&#39;s % (Testing Range)”">​</a></h2><ul><li><strong>Flour</strong> - 100%</li><li><strong>Water</strong> - 65-72%</li><li><strong>Salt</strong> - 2-2.5%</li><li><strong>Olive oil (in dough)</strong> - 2-4%</li><li><strong>Sugar</strong> - 0-2%</li><li><strong>Yeast (IDY)</strong> - 0.4-0.8%</li><li><strong>Pan oil</strong> - moderate to heavy</li></ul><h2 id="ingredients-example-batch" tabindex="-1">Ingredients (Example Batch) <a class="header-anchor" href="#ingredients-example-batch" aria-label="Permalink to “Ingredients (Example Batch)”">​</a></h2><ul><li><strong>Flour</strong> - 500g (100%)</li><li><strong>Water</strong> - 340g (68%)</li><li><strong>Salt</strong> - 11g (2.2%)</li><li><strong>Olive oil (in dough)</strong> - 15g (3%)</li><li><strong>Sugar</strong> - 5g (1%)</li><li><strong>Instant dry yeast</strong> - 3g (0.6%)</li></ul><p>Need a scale? <a href="https://amzn.to/48F9DfT" target="_blank" rel="noreferrer">KitchenAid Digital Scale</a>.</p><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>This batch generally fits a 9x13-inch pan for a medium-thick Sicilian profile.</p></div><hr><h2 id="procedure" tabindex="-1">Procedure <a class="header-anchor" href="#procedure" aria-label="Permalink to “Procedure”">​</a></h2><h3 id="_1-mixing" tabindex="-1">1. Mixing <a class="header-anchor" href="#_1-mixing" aria-label="Permalink to “1. Mixing”">​</a></h3><ul><li>Combine flour, yeast, sugar, and water until shaggy.</li><li>Rest 10 minutes.</li><li>Add salt and oil, then mix until smooth and cohesive.</li><li>Knead <strong>3-5 minutes</strong> or until medium development.</li></ul><h3 id="_2-bulk-fermentation" tabindex="-1">2. Bulk Fermentation <a class="header-anchor" href="#_2-bulk-fermentation" aria-label="Permalink to “2. Bulk Fermentation”">​</a></h3><ul><li>Ferment at room temperature for <strong>2-3 hours</strong>, with one fold halfway through.</li><li>For deeper flavor, move to the refrigerator overnight after the first hour.</li></ul><h3 id="_3-pan-and-stretch" tabindex="-1">3. Pan and Stretch <a class="header-anchor" href="#_3-pan-and-stretch" aria-label="Permalink to “3. Pan and Stretch”">​</a></h3><ul><li>Oil the pan generously.</li><li>Transfer dough and gently stretch to cover most of the pan.</li><li>If it resists, wait 10-15 minutes and continue.</li></ul><h3 id="_4-long-pan-proof" tabindex="-1">4. Long Pan Proof <a class="header-anchor" href="#_4-long-pan-proof" aria-label="Permalink to “4. Long Pan Proof”">​</a></h3><ul><li>Proof until dough is light, puffy, and visibly aerated.</li><li>Typical range is <strong>2-4 hours</strong> at room temperature.</li></ul><h3 id="_5-dimple-and-top" tabindex="-1">5. Dimple and Top <a class="header-anchor" href="#_5-dimple-and-top" aria-label="Permalink to “5. Dimple and Top”">​</a></h3><ul><li>Dimple with oiled fingertips to redistribute gas without crushing it.</li><li>Top evenly but avoid drowning the center.</li></ul><h3 id="_6-bake" tabindex="-1">6. Bake <a class="header-anchor" href="#_6-bake" aria-label="Permalink to “6. Bake”">​</a></h3><ul><li>Bake at <strong>450-500F</strong> until crust is golden and bottom is crisp, usually <strong>14-22 minutes</strong> depending on pan and thickness.</li><li>Rotate once if your oven has hot spots.</li></ul><h3 id="_7-rest" tabindex="-1">7. Rest <a class="header-anchor" href="#_7-rest" aria-label="Permalink to “7. Rest”">​</a></h3><ul><li>Rest 5 minutes in pan, then move to a rack to preserve bottom texture.</li></ul><h2 id="thickness-and-bake-guide-starting-point" tabindex="-1">Thickness and Bake Guide (Starting Point) <a class="header-anchor" href="#thickness-and-bake-guide-starting-point" aria-label="Permalink to “Thickness and Bake Guide (Starting Point)”">​</a></h2><table tabindex="0"><thead><tr><th>Pan size</th><th>Dough profile</th><th>Typical bake at 475F</th></tr></thead><tbody><tr><td>9x13</td><td>Classic medium-thick Sicilian</td><td>16-22 minutes</td></tr><tr><td>10x14</td><td>Lighter and a bit crisper</td><td>14-20 minutes</td></tr><tr><td>Half sheet</td><td>Thinner tray style</td><td>12-18 minutes</td></tr></tbody></table><h2 id="what-to-adjust-first" tabindex="-1">What to Adjust First <a class="header-anchor" href="#what-to-adjust-first" aria-label="Permalink to “What to Adjust First”">​</a></h2><ul><li><strong>Too dense</strong>: extend final pan proof.</li><li><strong>Too flat</strong>: reduce dough handling during stretch and topping.</li><li><strong>Bottom soft</strong>: increase pan oil slightly and finish lower in oven.</li></ul><h2 id="related-guides" tabindex="-1">Related Guides <a class="header-anchor" href="#related-guides" aria-label="Permalink to “Related Guides”">​</a></h2><div class="content-section"><ul><li><a href="/guides/hydration.html">Hydration</a></li><li><a href="/guides/fermentation.html">Fermentation</a></li><li><a href="/guides/folding.html">Folding</a></li></ul></div><h2 id="get-the-gear" tabindex="-1">Get the Gear <a class="header-anchor" href="#get-the-gear" aria-label="Permalink to “Get the Gear”">​</a></h2><div class="content-section"><ul><li><a href="/guides/baking-gear-and-ingredients.html">Baking Gear &amp; Ingredients</a></li></ul></div><h2 id="related-recipes" tabindex="-1">Related Recipes <a class="header-anchor" href="#related-recipes" aria-label="Permalink to “Related Recipes”">​</a></h2><div class="content-section"><ul><li><a href="/recipes/detroit-style-pan-pizza.html">Detroit Style Pan Pizza</a></li><li><a href="/recipes/cold-iron-cloud-pan-pizza.html">Cold Iron Cloud Pan Pizza</a></li></ul></div><hr><blockquote><p><strong>Affiliate Disclaimer</strong> This post contains affiliate links. As an Amazon Associate, I earn from qualifying purchases. If you click on a link and make a purchase, I may receive a small commission at no extra cost to you.</p></blockquote>',38)])])}const u=e(r,[["render",l]]);export{g as __pageData,u as default};
